function post_oidc() {
    console.log("post_oidc")
    fetch("/altme-identity/post_oidc", { method: "POST", headers: { email: document.getElementById("email").value } }).then((res) => {
        res.json().then(
            (data) => {
                if (data.status==="ok"){
                    let element2 = document.getElementById('emailDiv');
                    element2.remove()
                    let element = document.getElementById('frame11');
                    element.setAttribute("class","")
                    document.getElementById("step1").innerHTML= "Step 2 : Choose your crypto wallet"
                    document.getElementById("choose").innerHTML= "Choose your favorite wallet and get a proof of ownership !"
                    nonce = data.nonce
                }
            }
        )
    })
}


async function signMessageB() {
    console.log("waiting to sign "+nonce)
    const signature = await signMessage({
        message: nonce,
    })
    console.log(signature)
    fetch(link, { method: "GET", headers: { pubKey: getAccount().account, signature: signature } }).then((res) => {
        res.json().then((data) => {
            console.log(data);
            if (data.status === "ok") {
                console.log("address verfied")
                window.location.href=data.uri
            }
        })
    })

}


